$('langBtn').onclick=()=>{lang=lang==='ru'?'kk':'ru';document.documentElement.lang=lang;try{localStorage.setItem('pt_lang',lang)}catch(e){}applyLang();$('langBtn').textContent=lang==='ru'?'Қазақша':'Русский';$('mainTitle').textContent=lang==='ru'?'Транспорт Петропавловска':'Петропавл көлігі';$('subtitle').textContent=lang==='ru'?'Найди маршрут, остановку и спланируй поездку.':'Бағытты, аялдаманы тауып, сапарды жоспарлаңыз.';routeList($('search').value);renderCard(active);fillPlanner()};
let deferredInstall;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e;$('installBtn').classList.remove('hidden')});$('installBtn').onclick=async()=>{if(deferredInstall){deferredInstall.prompt();deferredInstall=null}};

if('serviceWorker' in navigator && location.protocol.startsWith('http'))navigator.serviceWorker.register('sw.js').catch(()=>{});

// ===== Dispatcher / local admin mode (no GPS) =====
const DKEY='petrotransit_dispatch_v4';
const dDefault={routes:routeData,service:{},alerts:[],timetable:{},feedback:[]};
function dLoad(){try{return JSON.parse(localStorage.getItem(DKEY))||structuredClone(dDefault)}catch(e){return JSON.parse(JSON.stringify(dDefault))}}
let dState=dLoad();for(const[kk,vv]of Object.entries({routes:routeData,service:{},alerts:[],timetable:{},feedback:[]}))if(!dState[kk])dState[kk]=vv;
for(const[k,v]of Object.entries(routeData))if(!dState.routes[k]&&!(dState.removed||[]).includes(k))dState.routes[k]=v;
const DATAV='2gis-2026-11';if(dState.dataV!==DATAV){dState.routes=JSON.parse(JSON.stringify(routeData));dState.removed=[];dState.dataV=DATAV}
let dLogged=false,dTab='overview';
const CFG=window.PT_CONFIG||{},REMOTE=!!(CFG.supabaseUrl&&CFG.anonKey);let sbToken=null,sbRT=null,sbRev=null,pushQ=Promise.resolve();
const sbH=a=>({apikey:CFG.anonKey,Authorization:'Bearer '+((a&&sbToken)||CFG.anonKey),'Content-Type':'application/json'});
function applyState(){routeData=dState.routes;routeList($('search').value);try{fillStopList();renderFavorites()}catch(e){}if(routeData[active]){renderCard(active);fillPlanner();startBuses()}dPublicRender();if(dLogged)dRender()}
async function remotePull(force){if(!REMOTE||(dLogged&&!force))return;try{const r=await fetch(CFG.supabaseUrl+'/rest/v1/app_state?id=eq.main&select=data,updated_at',{headers:sbH(false)});if(!r.ok)return;const j=await r.json();if(!j[0])return;sbRev=j[0].updated_at;const d=j[0].data||{};if(d.dataV!==DATAV){delete d.routes;delete d.dataV}delete d.feedback;if(d.routes&&!Object.values(d.routes).every(x=>x&&Array.isArray(x.stops)))delete d.routes;dState=Object.assign({},dState,d);try{localStorage.setItem(DKEY,JSON.stringify(dState))}catch(e){}applyState()}catch(e){}}
async function remotePush1(){if(!REMOTE||!sbToken)return;const{feedback,...data}=dState,body={data,updated_at:new Date().toISOString()},u=CFG.supabaseUrl+'/rest/v1/app_state',H=Object.assign(sbH(true),{Prefer:'return=representation'});
 try{const r=await fetch(u+'?id=eq.main'+(sbRev?'&updated_at=eq.'+encodeURIComponent(sbRev):''),{method:'PATCH',headers:H,body:JSON.stringify(body)});if(!r.ok)throw 0;const j=await r.json();
  if(j.length){sbRev=j[0].updated_at;return}
  if(!sbRev){const r2=await fetch(u,{method:'POST',headers:H,body:JSON.stringify(Object.assign({id:'main'},body))});if(!r2.ok)throw 0;sbRev=(await r2.json())[0].updated_at;return}
  alert('Общие данные уже изменил другой диспетчер. Загружена свежая версия — повторите правку.');await remotePull(true)}catch(e){alert('Не удалось сохранить в общую базу — изменения остались только на этом устройстве.')}}
const remotePush=()=>{pushQ=pushQ.then(remotePush1);return pushQ};
async function sbRefresh(){if(!sbRT)return;try{const r=await fetch(CFG.supabaseUrl+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:CFG.anonKey,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:sbRT})});const j=await r.json();if(j.access_token){sbToken=j.access_token;sbRT=j.refresh_token||sbRT}}catch(e){}}
if(REMOTE){$('dispatchEmail').classList.remove('hidden');$('dispatchPin').type='password';$('dispatchPin').placeholder='Пароль';$('dispatchLoginBtn').onclick=async()=>{const m=$('dispatchLoginMsg');m.textContent='Вход…';try{const r=await fetch(CFG.supabaseUrl+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:CFG.anonKey,'Content-Type':'application/json'},body:JSON.stringify({email:$('dispatchEmail').value.trim(),password:$('dispatchPin').value})}),j=await r.json();if(!r.ok||!j.access_token)throw new Error(j.msg||j.message||j.error_description||j.error||('HTTP '+r.status));sbToken=j.access_token;sbRT=j.refresh_token;dLogged=true;setInterval(sbRefresh,45*60000);await remotePull(true);$('dispatchLogin').classList.add('hidden');$('dispatchMain').classList.remove('hidden');m.textContent='';dRender()}catch(e){m.textContent='Ошибка входа: '+(e&&e.message?e.message:'неизвестная ошибка')}}}
$('dbStatus').textContent=REMOTE?'Режим: общая база данных — изменения видят все пользователи.':'Режим: демо, данные хранятся только в этом браузере (см. SETUP_DATABASE.md).';

const alertLive=a=>a.active!==false&&(!a.exp||a.exp>Date.now());
function dSave(){try{dSave0()}finally{try{fillStopList();renderFavorites();if(routeData[active])fillPlanner()}catch(e){}}}
function dSave0(){try{localStorage.setItem(DKEY,JSON.stringify(dState))}catch(e){alert('Не удалось сохранить: хранилище браузера недоступно или заполнено.')}remotePush();routeData=dState.routes;routeList($('search').value);if(routeData[active]){renderCard(active);fillPlanner();startBuses()}dPublicRender();dRender()}
function dOpen(){ $('dispatchApp').classList.add('open');$('dispatchLogin').classList.toggle('hidden',dLogged);$('dispatchMain').classList.toggle('hidden',!dLogged);if(dLogged)dRender();}
function dClose(){ $('dispatchApp').classList.remove('open');}
$('dispatchBtn').onclick=dOpen;
$('dispatchClose').onclick=dClose;
let pinFails=0,pinLock=0;if(!REMOTE){$('dispatchLoginBtn').onclick=()=>{if(Date.now()<pinLock){$('dispatchLoginMsg').textContent='Слишком много попыток. Подождите 30 секунд.';return}if($('dispatchPin').value===(localStorage.getItem('pt_pin')||'2468')){dLogged=true;$('dispatchLogin').classList.add('hidden');$('dispatchMain').classList.remove('hidden');$('dispatchLoginMsg').textContent='';dRender()}else{if(++pinFails>=5){pinLock=Date.now()+30000;pinFails=0}$('dispatchLoginMsg').textContent='Неверный PIN'}};}
document.querySelectorAll('[data-dtab]').forEach(b=>b.onclick=()=>{dTab=b.dataset.dtab;document.querySelectorAll('[data-dtab]').forEach(x=>x.classList.toggle('active',x===b));dRender()});
function dExtra(c){const q=id=>c.querySelector('#'+id);
 q('dPinSave').onclick=()=>{const v=q('dPinNew').value.trim();if(!/^\d{4,8}$/.test(v)){alert('PIN: 4–8 цифр');return}localStorage.setItem('pt_pin',v);q('dPinNew').value='';alert('PIN изменён (хранится только в этом браузере).')};
 q('dWarm').onclick=async()=>{const b=q('dWarm'),all=[];for(const[k,v]of Object.entries(dState.routes))for(const x of v.stops)all.push([x,/^\d{3}/.test(k)]);const u=[...new Map(all.map(a=>[a[0].toLowerCase(),a])).values()];let n=0,bad=0;const w=async()=>{while(n<u.length){const[x,sub]=u[n++];if(!(await geocode(x,null,sub)))bad++;b.textContent=`Поиск: ${n}/${u.length}`}};await Promise.all([1,2,3,4].map(w));saveGc();b.textContent=`Готово, не найдено: ${bad}. Теперь «Экспорт координат»`};
 q('dExportGeo').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(gc)],{type:'application/json'}));a.download='stops.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 q('dExport').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(dState,null,1)],{type:'application/json'}));a.download='petrotransit-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
 q('dImport').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const j=JSON.parse(await f.text());if(!j.routes||!Object.values(j.routes).every(r=>Array.isArray(r.stops)))throw 0;if(!confirm('Заменить локальные данные импортированными?'))return;dState=Object.assign({service:{},alerts:[],timetable:{},feedback:[]},j);if(!j.routes[active])active=Object.keys(j.routes)[0];dSave();selectRoute(active)}catch(err){alert('Файл не похож на экспорт PetroTransit.')}};}
function dEsc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function dRender(){
 if(!dLogged)return;
 let c=$('dispatchContent'),ks=Object.keys(dState.routes),alerts=dState.alerts.filter(alertLive),services=Object.values(dState.service);
 if(dTab==='overview'){
 c.innerHTML=`<h3>Сводка смены</h3><div class="dispatch-grid">
 <div class="dispatch-stat">Маршрутов<strong>${ks.length}</strong></div>
 <div class="dispatch-stat">Активных объявлений<strong>${alerts.length}</strong></div>
 <div class="dispatch-stat">Ручных статусов<strong>${services.length}</strong></div></div>
 <div class="card"><h3>Оперативная информация</h3><p class="muted">Данные вводятся сотрудником вручную. GPS, автоматическое отслеживание и синхронизация с автобусами отключены.</p>
 <div class="dispatch-actions"><button class="btn primary" data-jump="alerts">Создать объявление</button><button class="btn" data-jump="service">Обновить статус маршрута</button><button class="btn" data-jump="routes">Редактировать маршрут</button></div></div>
 <div class="card"><h3>Служебное</h3><div class="dispatch-form"><label>Новый PIN (4–8 цифр)<input id="dPinNew" type="password" inputmode="numeric"></label><div class="dispatch-actions"><button class="btn" id="dPinSave">Сменить PIN</button><button class="btn" id="dExport">Экспорт JSON</button><button class="btn" id="dWarm">Найти координаты всех маршрутов</button><button class="btn" id="dExportGeo">Экспорт координат (stops.json)</button><label class="btn" style="cursor:pointer">Импорт JSON<input id="dImport" type="file" accept="application/json" hidden></label></div></div></div><h3>Последние объявления</h3>${alerts.slice(0,5).map(a=>`<div class="public-alert"><b>${dEsc(a.title)}</b><div>${dEsc(a.text)}</div><small>${dEsc(a.date||'')}</small></div>`).join('')||'<p class="muted">Объявлений нет.</p>'}`;
 dExtra(c);c.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{dTab=b.dataset.jump;document.querySelectorAll('[data-dtab]').forEach(x=>x.classList.toggle('active',x.dataset.dtab===dTab));dRender()});
 }
 if(dTab==='routes'){
 c.innerHTML=`<h3>Маршруты и остановки</h3><p class="muted">Изменения сохраняются в этом браузере. Для общей базы всех сотрудников нужен сервер.</p>
 <label class="muted">Выберите маршрут</label><select id="dRoute">${ks.map(k=>`<option value="${dEsc(k)}">${dEsc(k)} — ${dEsc(dState.routes[k].name_ru)}</option>`).join('')}</select>
 <div class="dispatch-form"><label>Номер/код маршрута<input id="dRouteKey" placeholder="Например, 7"></label><label>Название маршрута<input id="dRouteName"></label><label class="wide">Остановки (каждая с новой строки)<textarea id="dRouteStops"></textarea></label></div>
 <div class="dispatch-actions"><button class="btn primary" id="dRouteSave">Сохранить маршрут</button><button class="btn" id="dRouteNew">Новый маршрут</button><button class="btn" id="dRouteDelete">Удалить выбранный</button></div><div class="statusmsg" id="dRouteMsg"></div>`;
 let sel=$('dRoute');function loadRoute(){let k=sel.value,r=dState.routes[k];$('dRouteKey').value=k;$('dRouteName').value=r.name_ru||'';$('dRouteStops').value=(r.stops||[]).join('\n');}
 sel.onchange=loadRoute;loadRoute();
 $('dRouteNew').onclick=()=>{$('dRouteKey').value='';$('dRouteName').value='';$('dRouteStops').value='';$('dRouteKey').focus()};
 $('dRouteSave').onclick=()=>{let k=$('dRouteKey').value.trim(),name=$('dRouteName').value.trim(),stops=$('dRouteStops').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!k||!name||stops.length<2){$('dRouteMsg').textContent='Заполните код, название и минимум две остановки.';return}const old=dState.routes[k];dState.routes[k]={name_ru:name,name_kk:(old&&old.name_ru===name&&old.name_kk)||name,stops};dSave();selectRoute(k);$('dRouteMsg').textContent='Маршрут сохранён.';};
 $('dRouteDelete').onclick=()=>{let k=sel.value;if(confirm('Удалить маршрут '+k+'?')){delete dState.routes[k];(dState.removed=dState.removed||[]).push(k);if(active===k)active=Object.keys(dState.routes)[0];dSave();selectRoute(active)}};
 }
 if(dTab==='service'){
 c.innerHTML=`<h3>Ручные статусы движения</h3><p class="muted">Не GPS. Диспетчер вручную публикует статус по маршруту.</p>
 <div class="dispatch-form"><label>Маршрут<select id="dServiceRoute">${ks.map(k=>`<option>${dEsc(k)}</option>`).join('')}</select></label><label>Статус<select id="dServiceStatus"><option>По расписанию</option><option>Задержка</option><option>Временно не работает</option><option>Изменён маршрут</option><option>Восстановлено движение</option></select></label><label class="wide">Комментарий для пассажиров<input id="dServiceNote" placeholder="Например: задержка около 10 минут"></label></div><button class="btn primary" id="dServiceSave">Опубликовать статус</button>
 <h3 style="margin-top:20px">Опубликованные статусы</h3><table class="dispatch-table"><tr><th>Маршрут</th><th>Статус</th><th>Комментарий</th><th></th></tr>${Object.entries(dState.service).map(([k,v])=>`<tr><td>${dEsc(k)}</td><td>${dEsc(v.status)}</td><td>${dEsc(v.note)}</td><td><button class="btn small" data-delservice="${dEsc(k)}">Снять</button></td></tr>`).join('')}</table>`;
 $('dServiceSave').onclick=()=>{let k=$('dServiceRoute').value;dState.service[k]={status:$('dServiceStatus').value,note:$('dServiceNote').value,updated:new Date().toLocaleString()};dSave()};
 c.querySelectorAll('[data-delservice]').forEach(b=>b.onclick=()=>{delete dState.service[b.dataset.delservice];dSave()});
 }
 if(dTab==='alerts'){
 c.innerHTML=`<h3>Объявления для пассажиров</h3><div class="dispatch-form"><label>Заголовок<input id="dAlertTitle" placeholder="Изменение движения"></label><label>Срок действия<select id="dAlertDuration"><option value="1">1 день</option><option value="7">7 дней</option><option value="0">Без срока (снять вручную)</option></select></label><label class="wide">Текст объявления<textarea id="dAlertText" placeholder="Какие маршруты затронуты, что изменилось…"></textarea></label></div><button class="btn primary" id="dAlertPublish">Опубликовать</button><h3 style="margin-top:20px">История объявлений</h3>${dState.alerts.map((a,i)=>`<div class="card"><div class="row"><b>${dEsc(a.title)}</b><button class="btn small" data-alertdel="${i}">Удалить</button></div><p class="muted">${dEsc(a.text)}</p><small>${dEsc(a.date||'')} · ${a.active===false?'Снято':'Активно'}</small><div class="dispatch-actions"><button class="btn small" data-alerttoggle="${i}">${a.active===false?'Активировать':'Снять с публикации'}</button></div></div>`).join('')||'<p class="muted">Объявлений ещё нет.</p>'}`;
 $('dAlertPublish').onclick=()=>{let title=$('dAlertTitle').value.trim(),text=$('dAlertText').value.trim();if(!title||!text){alert('Введите заголовок и текст');return}dState.alerts.unshift({title,text,date:new Date().toLocaleString(),active:true,exp:(+$('dAlertDuration').value)?Date.now()+(+$('dAlertDuration').value)*864e5:0});dSave()};
 c.querySelectorAll('[data-alertdel]').forEach(b=>b.onclick=()=>{dState.alerts.splice(+b.dataset.alertdel,1);dSave()});
 c.querySelectorAll('[data-alerttoggle]').forEach(b=>b.onclick=()=>{let a=dState.alerts[+b.dataset.alerttoggle];a.active=a.active===false;dSave()});
 }
 if(dTab==='timetable'){
 c.innerHTML=`<h3>Расписание (ручной справочник)</h3><p class="muted">Здесь можно указать время/интервал, который видят пассажиры. Не является GPS-прогнозом.</p><div class="dispatch-form"><label>Маршрут<select id="dTimeRoute">${ks.map(k=>`<option>${dEsc(k)}</option>`).join('')}</select></label><label>Дни<select id="dTimeDays"><option>Ежедневно</option><option>Будни</option><option>Выходные</option></select></label><label>Начало движения<input id="dTimeStart" placeholder="06:30"></label><label>Окончание<input id="dTimeEnd" placeholder="22:00"></label><label>Интервал<input id="dTimeInterval" placeholder="10–15 минут"></label><label>Примечание<input id="dTimeNote" placeholder="Уточняйте у перевозчика"></label></div><button class="btn primary" id="dTimeSave">Сохранить расписание</button><h3>Сохранённые данные</h3><table class="dispatch-table"><tr><th>Маршрут</th><th>Дни</th><th>Время</th><th>Интервал</th><th></th></tr>${Object.entries(dState.timetable).map(([k,v])=>`<tr><td>${dEsc(k)}</td><td>${dEsc(v.days)}</td><td>${dEsc(v.start)}–${dEsc(v.end)}</td><td>${dEsc(v.interval)}</td><td><button class="btn small" data-time-del="${dEsc(k)}">Удалить</button></td></tr>`).join('')}</table>`;
 $('dTimeSave').onclick=()=>{let k=$('dTimeRoute').value;dState.timetable[k]={days:$('dTimeDays').value,start:$('dTimeStart').value,end:$('dTimeEnd').value,interval:$('dTimeInterval').value,note:$('dTimeNote').value};dSave()};
 c.querySelectorAll('[data-time-del]').forEach(b=>b.onclick=()=>{delete dState.timetable[b.dataset.timeDel];dSave()});
 }
 if(dTab==='feedback'){
  c.innerHTML=`<h3>Обращения пассажиров</h3><p class="muted">Сообщения из формы обратной связи поступают сюда автоматически.</p><div id="feedbackInbox" class="muted">Загрузка обращений…</div><button class="btn" id="feedbackReload">Обновить</button>`;
  const loadFeedback=async()=>{const box=$('feedbackInbox');box.textContent='Загрузка обращений…';try{const r=await fetch(CFG.supabaseUrl+'/rest/v1/report_submissions?select=id,route,stop,description,created_at,status&order=created_at.desc',{headers:sbH(true)});if(!r.ok)throw new Error('HTTP '+r.status);const rows=await r.json();box.innerHTML=rows.map(x=>`<div class="card"><div class="row"><b>${dEsc(x.route?'Маршрут '+x.route:'Ошибка маршрута')}</b><span class="dispatch-badge">${dEsc(x.status==='done'?'Обработано':'Новое')}</span></div><p><b>Остановка:</b> ${dEsc(x.stop||'Не указана')}</p><p>${dEsc(x.description)}</p><small class="muted">${dEsc(new Date(x.created_at).toLocaleString())}</small>${x.status!=='done'?`<div class="dispatch-actions"><button class="btn small" data-feedback-done="${dEsc(x.id)}">Отметить обработанным</button></div>`:''}</div>`).join('')||'<p class="muted">Обращений пока нет.</p>';box.querySelectorAll('[data-feedback-done]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const rr=await fetch(CFG.supabaseUrl+'/rest/v1/report_submissions?id=eq.'+encodeURIComponent(b.dataset.feedbackDone),{method:'PATCH',headers:Object.assign(sbH(true),{Prefer:'return=minimal'}),body:JSON.stringify({status:'done'})});if(!rr.ok)throw new Error('HTTP '+rr.status);loadFeedback()}catch(e){alert('Не удалось обновить обращение: '+e.message);b.disabled=false}})}catch(e){box.textContent='Не удалось загрузить обращения. Проверьте, что выполнили обновлённый supabase_setup.sql. '+e.message}};loadFeedback();$('feedbackReload').onclick=loadFeedback;

 }
}
function dPublicRender(){
 let activeAlerts=dState.alerts.filter(alertLive);
 $('publicAlerts').innerHTML=activeAlerts.map(a=>`<div class="public-alert"><b>⚠ ${dEsc(a.title)}</b><div>${dEsc(a.text)}</div><small>${dEsc(a.date||'')}</small></div>`).join('');
 $('publicServiceStatus').innerHTML=Object.entries(dState.service).map(([k,v])=>`<div class="public-service"><b>Маршрут ${dEsc(k)} · ${dEsc(v.status)}</b><div>${dEsc(v.note||'')}</div><small>Обновлено: ${dEsc(v.updated||'')}</small></div>`).join('');
}
dPublicRender();

const I18N={kk:{tabRoutes:'Бағыттар',tabFav:'Таңдаулы',tabTrip:'Жол',tabInfo:'Көмек',shareBtn:'Бөлісу',cityBtn:'Петропавл',trafficBtn:'Демо-кептелістер',dispatchBtn:'Диспетчерлік',myLocation:'Менің орным',planTrip:'Учаскені көрсету',reportBtn:'Қате туралы хабарлау'},ru:{}};
for(const id in I18N.kk)I18N.ru[id]=$(id)?$(id).textContent:'';
function applyLang(){const d=I18N[lang];for(const id in d){const e=$(id);if(e&&d[id])e.textContent=d[id]}$('search').placeholder=lang==='kk'?'Бағыт немесе аялдама іздеу…':'Поиск маршрута или остановки…'}
{const sw=document.createElement('button');sw.className='btn';sw.textContent='⇅';sw.title='Поменять местами / Орындарын ауыстыру';sw.onclick=()=>{const a=$('fromStop').selectedIndex;$('fromStop').selectedIndex=$('toStop').selectedIndex;$('toStop').selectedIndex=a};$('planTrip').after(sw)}
const ob=()=>$('offBar').classList.toggle('hidden',navigator.onLine);addEventListener('online',ob);addEventListener('offline',ob);ob();
routeData=dState.routes;
let hr='',last='';try{hr=decodeURIComponent((location.hash.match(/route=([^&]+)/)||[])[1]||'');last=localStorage.getItem('pt_last')||''}catch(e){}
active=routeData[hr]?hr:routeData[last]?last:routeData[active]?active:Object.keys(routeData)[0];
try{if(localStorage.getItem('pt_lang')==='kk')$('langBtn').onclick()}catch(e){}
remotePull();setInterval(()=>{if(!document.hidden)remotePull()},60000);routeList();fetch('stops.json').then(r=>r.ok?r.json():{}).catch(()=>({})).then(j=>{for(const k in j)if(!gc[k]&&Array.isArray(j[k]))gc[k]=j[k];selectRoute(active);setTimeout(warmAll,4000)});

// ===== Время прибытия: расчёт по расписанию (НЕ GPS) / Келу уақыты =====
const ETA={speed:18,dwell:20,gap:450};
const tt=(ru,kk)=>lang==='kk'?kk:ru;
// Ориентировочные интервалы (предположение, НЕ данные перевозчика): используются, пока диспетчер не задал расписание
function etaTT(k){const t=dState.timetable[k];if(t)return t;
 if(/^1\d\d$/.test(k))return{days:'Ежедневно',start:'07:00',end:'20:00',interval:'60',assumed:true};
 if(/М$/i.test(k))return{days:'Ежедневно',start:'06:30',end:'22:00',interval:'10',assumed:true};
 return{days:'Ежедневно',start:'06:30',end:'22:00',interval:'15',assumed:true}}
const etaHM=s=>{const q=/^(\d{1,2})[:.](\d{2})$/.exec((s||'').trim());return q?+q[1]*60+ +q[2]:null};
const etaIvl=s=>{const t=String(s||''),n=(t.match(/\d+(?:[.,]\d+)?/g)||[]).map(x=>+x.replace(',','.')).filter(x=>x>0);if(!n.length)return 0;let v=n.reduce((a,b)=>a+b)/n.length;if(/час|сағ/i.test(t))v*=60;return v};
const etaClock=ts=>{const d=new Date(ts);return String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};
function etaWhen(ts,now){const m=Math.round((ts-now)/60000),d0=new Date(now),d1=new Date(ts),dd=Math.round((new Date(d1.getFullYear(),d1.getMonth(),d1.getDate())-new Date(d0.getFullYear(),d0.getMonth(),d0.getDate()))/864e5);
 const day=dd===1?' '+tt('завтра','ертең'):dd>1?' '+d1.toLocaleDateString(lang==='kk'?'kk-KZ':'ru-RU',{day:'numeric',month:'short'}):'';
 const h=Math.floor(m/60),r=m<=0?tt('сейчас','қазір'):m<60?tt(`через ${m} мин`,`${m} мин кейін`):tt(`через ${h} ч ${m%60} мин`,`${h} сағ ${m%60} мин кейін`);return `${r} (${etaClock(ts)}${day})`}
// Расстояние вдоль маршрута (м) для каждой остановки; пропуски заполняются интерполяцией
function etaDist(k){const n=routeData[k].stops.length,f=(coords[k]||[]).slice().sort((a,b)=>a.index-b.index),
 path=(k===active&&lc[curHK])||(f.length>1?f.map(x=>x.p):null),d=new Array(n).fill(null);
 if(path&&path.length>1){const cum=[0];for(let i=1;i<path.length;i++)cum.push(cum[i-1]+map.distance(path[i-1],path[i]));let prev=0;
  for(const x of f){let bi=0,bd=1e12;for(let i=0;i<path.length;i++){const q=map.distance(x.p,path[i]);if(q<bd){bd=q;bi=i}}prev=Math.max(prev,cum[bi]);d[x.index]=prev}}
 const kn=[];d.forEach((v,i)=>{if(v!=null)kn.push(i)});
 if(kn.length<2||d[kn[kn.length-1]]-d[kn[0]]<100)return d.map((_,i)=>i*ETA.gap);
 for(let i=0;i<n;i++){if(d[i]!=null)continue;const lo=kn.filter(j=>j<i).pop(),hi=kn.find(j=>j>i);
  if(lo==null)d[i]=Math.max(0,d[hi]-(hi-i)*ETA.gap);else if(hi==null)d[i]=d[lo]+(i-lo)*ETA.gap;else d[i]=d[lo]+(d[hi]-d[lo])*(i-lo)/(hi-lo)}
 return d}
const etaRide=(d,a,b)=>Math.abs(d[b]-d[a])/1000/ETA.speed*60+Math.abs(b-a)*ETA.dwell/60;
// Времена отправления с конечной остановки (мс), начиная с fromMs
function etaDeps(k,fromMs,count,offMin){const t=etaTT(k);
 const a=etaHM(t.start),b=etaHM(t.end),iv=etaIvl(t.interval);if(a==null||b==null||!iv)return null;
 const out=[],base=new Date(fromMs);
 for(let off=-1;off<=7&&out.length<count;off++){const day=new Date(base.getFullYear(),base.getMonth(),base.getDate()+off),we=day.getDay()%6===0;
  if(t.days==='Будни'&&we||t.days==='Выходные'&&!we)continue;
  const s0=day.getTime()+a*60000;let e0=day.getTime()+b*60000;if(b<a)e0+=864e5;
  for(let m=0;s0+m*60000<=e0&&out.length<count;m+=iv){const ts=s0+(m+offMin)*60000;if(ts>=fromMs)out.push(ts)}}
 return out}
function etaAt(k,i,count=3){const now=Date.now(),sv=dState.service[k];if(sv&&sv.status==='Временно не работает')return{off:true};
 const t=etaTT(k),iv=etaIvl(t.interval),last=routeData[k].stops.length-1,d=etaDist(k),res=[];
 const fw=etaRide(d,0,i),bw=etaRide(d,last,i);
 if(i<last){const x=etaDeps(k,now-fw*60000,count,0);if(!x)return{none:true,fw,bw};x.forEach(ts=>res.push({ts:ts+fw*60000,dir:1}))}
 if(i>0){const x=etaDeps(k,now-bw*60000,count,iv/2);if(x)x.forEach(ts=>res.push({ts:ts+bw*60000,dir:-1}))}
 res.sort((p,q)=>p.ts-q.ts);return{list:res.slice(0,count),fw,bw,assumed:!!t.assumed,delay:sv&&sv.status==='Задержка'}}
function etaStatic(){const s=(id,v)=>{const e=$(id);if(e)e.textContent=v};s('etaTitle',tt('Время прибытия','Келу уақыты'));s('etaNear',tt('📍 Ближайшая ко мне','📍 Маған жақын аялдама'));
 s('etaNote',tt('Расчёт по расписанию диспетчерской и длине маршрута (≈18 км/ч + 20 с на остановку), не по GPS. Фактическое время может отличаться.','Диспетчерлік кесте мен бағыт ұзындығы бойынша есептеледі (≈18 км/сағ + аялдамада 20 сек), GPS бойынша емес. Нақты уақыт өзгеше болуы мүмкін.'))}
function etaUpdate(){try{etaUpdate0()}catch(e){}}
function etaUpdate0(){const out=$('etaOut'),sel=$('etaStop');if(!out||!sel||!routeData[active])return;const i=+sel.value;if(sel.value===''||isNaN(i)){out.textContent=tt('Выберите остановку','Аялдама таңдаңыз');return}
 const k=active,st=routeData[k].stops,r=etaAt(k,i),now=Date.now();
 if(r.off){out.textContent=tt('Маршрут временно не работает (по данным диспетчерской).','Бағыт уақытша жұмыс істемейді (диспетчерлік деректері бойынша).');return}
 if(r.none){out.textContent=tt(`Для маршрута ${k} не задано время движения и интервал. От начальной остановки ≈ ${Math.round(r.fw)} мин.`,`${k} бағыты үшін қозғалыс уақыты мен аралығы көрсетілмеген. Бастапқы аялдамадан ≈ ${Math.round(r.fw)} мин.`);return}
 if(!r.list.length){out.textContent=tt('Ближайших рейсов по справочнику не найдено.','Кесте бойынша жақын рейстер табылмады.');return}
 out.innerHTML=r.list.map(x=>{const n=dEsc(sn(st[x.dir>0?st.length-1:0]));return `<div>🚌 ${dEsc(etaWhen(x.ts,now))} · ${tt(`в сторону «${n}»`,`«${n}» бағытына`)}</div>`}).join('')
  +(r.assumed?`<div class="muted">ℹ ${tt('Ориентировочное расписание: интервал предположительный, диспетчер его ещё не подтвердил.','Шамамен алынған кесте: аралық болжамды, диспетчер әлі растаған жоқ.')}</div>`:'')
  +(r.delay?`<div class="muted">⚠ ${tt('На маршруте объявлена задержка — рейсы могут опаздывать.','Бағытта кешігу жарияланған — рейстер кешігуі мүмкін.')}</div>`:'')}
function etaFill(){try{etaFill0()}catch(e){}}
function etaFill0(){etaStatic();const sel=$('etaStop');if(!sel||!routeData[active])return;const prev=sel.dataset.route===active?sel.value:'';
 sel.innerHTML=routeData[active].stops.map((s,i)=>`<option value="${i}">${i+1}. ${dEsc(sn(s))}</option>`).join('');sel.dataset.route=active;if(prev!=='')sel.value=prev;etaUpdate()}
function etaTrip(k,a,b){try{const d=etaDist(k),now=Date.now(),t=etaTT(k),iv=etaIvl(t.interval),sv=dState.service[k];
 if(sv&&sv.status==='Временно не работает')return' '+tt('Маршрут временно не работает.','Бағыт уақытша жұмыс істемейді.');
 const ride=etaRide(d,a,b),fwd=a<b,pre=etaRide(d,fwd?0:d.length-1,a),x=etaDeps(k,now-pre*60000,1,fwd?0:iv/2),nm=sn(routeData[k].stops[a]);
 if(!x||!x.length)return tt(` В пути ≈ ${Math.round(ride)} мин (расписание не задано, ожидание не учтено).`,` Жолда ≈ ${Math.round(ride)} мин (кесте көрсетілмеген, күту ескерілмеген).`);
 const board=x[0]+pre*60000,as=t.assumed?tt(' Расписание ориентировочное.',' Кесте шамамен алынған.'):'';
 return tt(` Ближайший автобус на остановке «${nm}»: ${etaWhen(board,now)}; в пути ≈ ${Math.round(ride)} мин; прибытие ≈ ${etaClock(board+ride*60000)}. Расчёт по расписанию, не GPS.${as}`,
  ` «${nm}» аялдамасындағы ең жақын автобус: ${etaWhen(board,now)}; жолда ≈ ${Math.round(ride)} мин; келу ≈ ${etaClock(board+ride*60000)}. Кесте бойынша есептеледі, GPS емес.${as}`)}catch(e){return''}}
$('etaStop').onchange=etaUpdate;
$('etaNear').onclick=()=>{if(!navigator.geolocation){msg(tt('Браузер не поддерживает геолокацию.','Браузер геолокацияны қолдамайды.'));return}navigator.geolocation.getCurrentPosition(pos=>{const p=[pos.coords.latitude,pos.coords.longitude],f=coords[active]||[];if(!f.length){msg(tt('Координаты остановок ещё загружаются.','Аялдама координаттары әлі жүктелуде.'));return}let b=f[0];for(const x of f)if(map.distance(p,x.p)<map.distance(p,b.p))b=x;$('etaStop').value=b.index;etaUpdate();msg(tt(`Ближайшая остановка: ${b.name} (≈ ${Math.round(map.distance(p,b.p))} м).`,`Ең жақын аялдама: ${b.name} (≈ ${Math.round(map.distance(p,b.p))} м).`))},()=>msg(tt('Не удалось получить местоположение. Разрешите доступ в браузере.','Орналасуды анықтау мүмкін болмады. Браузерде рұқсат беріңіз.')))};
setInterval(etaUpdate,20000);
